protected int removeRandomItems(Random rand, List<ItemStack> loot, int count) {
		if(loot.isEmpty()) {
			return 0;
		}

		for(int i = 0; i < count; i++) {
			int randStack = rand.nextInt(loot.size());
			ItemStack stack = loot.get(randStack);

			stack.shrink(1);

			if(stack.isEmpty()) {
				loot.remove(randStack);
			}

			if(loot.isEmpty()) {
				return i;
			}
		}

		return count;
	}

