	protected void setBlockAndNotifyAdequately(World worldIn, BlockPos pos, IBlockState state) {
		if(this.isProtectedBlock(state)) {
			this.guard.setGuarded(worldIn, pos, true);
		} else {
			this.guard.setGuarded(worldIn, pos, false);
